def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Returns priority with which we want to add item to each bin.
    Args:
        item: Size of item to be added to the bin.
        bins: Array of capacities for each bin.
    Return:
        Array of same size as bins with priority score of each bin.
    """
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    total_rem = np.sum(remaining[valid])
    if total_rem == 0:
        p = np.zeros_like(remaining)
    else:
        p = remaining / (total_rem + 1e-8)
    entropy = -np.sum(np.where((valid) & (p > 0), p * np.log(p + 1e-12), 0))
    priorities = entropy * (remaining / (np.max(bins) + 1e-8))
    return np.where(valid, priorities, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
